        cout << "Error: Both integers must be non-negative." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numSequenceElements;

    if (numSequenceElements <= 0) {
        cout << "Error: The number of sequence elements must be positive." << endl;
        return 1;
    }

    int sequence[numSequenceElements];
    sequence[0] = num1;
    sequence[1] = num2;

    for (int i = 2; i < numSequenceElements; i++) {
