  var placeName = "New York"; // Replace with the place name you want to search for

  var geocoder = new google.maps.Geocoder();

  geocoder.geocode({ address: placeName }, function(results, status) {
    if (status === 'OK') {
      var latitude = results[0].geometry.location.lat();
      var longitude = results[0].geometry.location.lng();

      for (var i = 1; i <= dataRange.getNumRows(); i++) {
        var cell = dataRange.getCell(i, 2); // Assuming the latitude column is in column C
        cell.setValue(latitude);

        cell = dataRange.getCell(i, 3); // Assuming the longitude column is in column D
        cell.setValue(longitude);
      }

      sheet.setActiveRange(dataRange);
    } else {
      sheet.setActiveRange(dataRange);
      sheet.getRange("E2").setValue("Error: " + status);
    }
  });
}
```

This script will search for the place name "New York" in the specified data range, and store the latitude and longitude in columns C and D, respectively. If there's an error, it will display an error message in column E.

