Here's a simple C function that converts an array of arguments (argv) to a null-terminated string:

```c
#include <stdio.h>
#include <stdlib.h>

char *argv_to_string(int argc, char **argv) {
    char *str = malloc(argc * sizeof(char *) + 1);
    int i;

    for (i = 0; i < argc; i++) {
        strcat(str, argv[i]);
        if (i < argc - 1) {
            strcat(str, " ");
        }
    }

    strcat(str, "\0"); // Add null terminator

    return str;
}

int main(int argc, char **argv) {
    char *str = argv_to_string(argc, argv);
    printf("Stringified argv: %s\n", str);
    free(str);

    return 0;
}
```

This function takes two arguments: the number of arguments in `argc` and the array of arguments in `argv`. It allocates memory for a string that can hold all the arguments concatenated together with spaces in between. It then iterates through the `argv` array, concatenating each argument to the string and adding a space if it's not the last argument. Finally, it adds a null terminator to the end of the string and returns it.

