}

// Query the database for loyal customers
$sql = "SELECT customer_id, COUNT(*) as purchase_count
FROM transactions
WHERE product_id = 'specific_product' AND purchase_date BETWEEN DATE_SUB(CURDATE(), INTERVAL 1 WEEK) AND CURDATE()
