To create a simple toast notification using React Context, follow these steps:

1. First, create a ToastContext.js file to define the context and provider:

```javascript
// src/components/ToastContext.js
import { createContext, useState } from 'react';

const ToastContext = createContext();

function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);

  const addToast = (message) => {
    setToasts((prevToasts) => [...prevToasts, message]);
  };

  return (
    <ToastContext.Provider value={{ addToast }}>
      {children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```

2. Next, create a Toast.js file to define the toast component:

```javascript
// src/components/Toast.js
import React from 'react';
import { useContext } from 'react';
import ToastContext from './ToastContext';

function Toast() {
  const { addToast } = useContext(ToastContext);

  const handleClick = () => {
    addToast('This is a toast notification!');
  };

  return (
    <button onClick={handleClick}>Show Toast</button>
  );
}

export default Toast;
```

3. Now, you can use the Toast component in your app:

```javascript
// src/App.js
import React from 'react';
import Toast from './Toast';
import ToastProvider from './ToastContext';

function App() {
  return (
    <ToastProvider>
      <div className="App">
        <Toast />
      </div>
    </ToastProvider>
  );
}

export default App;
```

With this setup, you can now display toast notifications in your React application by clicking the "Show Toast" button. The toast will be added to the list of toasts and displayed at the top of the screen.

