2. Close Camera and Microphone:
```javascript
function closeCameraAndMicrophone() {
  const streams = navigator.mediaDevices.enumerateDevices();
  streams.forEach(stream => {
    if (stream.kind === 'video' || stream.kind === 'audio') {
      stream.stop();
    }
  });
}
```
