Here's the `redis.js` file inside the `utils` folder:

```javascript
class RedisClient {
  constructor() {
    const redis = require('redis');
    this.client = new redis();

    this.client.on('error', (err) => {
      console.error('Error with Redis client:', err);
    });
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (err) {
      return false;
    }
  }

  async get(key) {
    try {
      const result = await this.client.get(key);
      return result;
    } catch (err) {
      throw new Error(`Error getting ${key} from Redis:`, err);
    }
  }

  async set(key, value, duration) {
    try {
      await this.client.setex(key, duration, value);
    } catch (err) {
      throw new Error(`Error setting ${key} in Redis:`, err);
    }
  }

  async del(key) {
    try {
      await this.client.del(key);
    } catch (err) {
      throw new Error(`Error deleting ${key} from Redis:`, err);
    }
  }
}

const redisClient = new RedisClient();

module.exports = { redisClient };
```

