Here's a Go code that identifies if a given sentence contains a double negative using the specified approach:

```go
package main

import (
	"fmt"
	"strings"
)

func isDoubleNegative(sentence string) bool {
	negativeWords := []string{"not", "never", "rarely", "seldom", "barely", "hardly"}
	words := strings.Split(sentence, " ")

	for _, word := range words {
		if containsNegativeWord(word) && hasNotFollowedByNegativeWord(word, words) {
			return true
		}
	}

	return false
}

func containsNegativeWord(word string) bool {
	for _, negativeWord := range negativeWords {
		if word == negativeWord || word == "-" + negativeWord {
			return true
		}
	}

	return false
}

func hasNotFollowedByNegativeWord(word string, words []string) bool {
	for i := 1; i < len(words); i++ {
		if words[i] == "not" && words[i-1] == word {
			return false
		}
	}

	return true
}

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	if isDoubleNegative(sentence) {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}
```

This code defines three functions: `isDoubleNegative`, `containsNegativeWord`, and `hasNotFollowedByNegativeWord`. The `isDoubleNegative` function checks if a given sentence contains a double negative by iterating through each word in the sentence and checking if it contains a negative word from the `negativeWords` slice and if it is not followed by the word "not". The `containsNegativeWord` function checks if a given word is a negative word from the `negativeWords` slice. The `hasNotFollowedByNegativeWord` function checks if a given word is not

