        $searcher.Filter = $filter
        $results = $searcher.FindAll()

        return ($results.Count -gt 0)
    } catch {
        Write-Host "Error checking SID: $_"
        return $false
    }
}

# Recursively check all subfolders and files in the starting path
function CheckFolderAcls($path) {
    Get-ChildItem -Path $path -Directory | ForEach-Object {
        $subPath = $_.FullName
        CheckFolderAcls($subPath)
    }

    Get-ChildItem -Path $path -File | ForEach-Object {
        $filePath = $_.FullName
        (Get-Acl $filePath).Access | ForEach-Object {
            if ($_.IdentityReference -match "^S-1-5-21-") {
                $sid = $_.IdentityReference
                if (!CheckSidInSIDHistory($sid)) {
                    Write-Host "ACL SID $sid not found in SIDHistory of any user or group in the domain"
                }
            }
        }
    }
}

# Start the search at the specified path
CheckFolderAcls($startPath)
```

Replace `"your_domain_name"` with your actual domain name, and `"C:\path
